describe('Email Field Inline Validation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('input[type="email"]').as('emailInput');
  });

  it('should display validation error message for invalid email format', () => {
    cy.get('@emailInput').type('invalidemail');
    cy.get('@emailInput').blur();
    cy.get('[data-testid="email-error"]').should('be.visible').and('contain', 'Please enter a valid email');
  });

  it('should display success state for valid email format', () => {
    cy.get('@emailInput').type('user@example.com');
    cy.get('@emailInput').blur();
    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.get('@emailInput').should('have.css', 'border-color', 'rgb(34, 197, 94)');
  });

  it('should show validation error while typing incomplete email', () => {
    cy.get('@emailInput').type('user@');
    cy.get('[data-testid="email-error"]').should('be.visible');
  });

  it('should clear validation error when user corrects the email', () => {
    cy.get('@emailInput').type('invalid');
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('@emailInput').clear().type('valid@email.com');
    cy.get('[data-testid="email-error"]').should('not.exist');
  });

  it('should handle edge case with special characters in email', () => {
    cy.get('@emailInput').type('user+tag@example.co.uk');
    cy.get('@emailInput').blur();
    cy.get('[data-testid="email-error"]').should('not.exist');
  });

  it('should display error for email with spaces', () => {
    cy.get('@emailInput').type('user @example.com');
    cy.get('@emailInput').blur();
    cy.get('[data-testid="email-error"]').should('be.visible').and('contain', 'valid email');
  });

  it('should validate empty email field on blur', () => {
    cy.get('@emailInput').focus().blur();
    cy.get('[data-testid="email-error"]').should('be.visible').and('contain', 'Email is required');
  });
});
